{
  "a_sentences": [
    {
      "a_text": "Le litige porte sur le droit de la personne assurée à une rente de l'assurance-invalidité à la suite de sa nouvelle demande déposée le 28 avril 2020.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "La personne assurée soutient que l'invalidité s'évalue en l'espèce à l'aune de ses limitations effectives, et non d'un marché du travail équilibré.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Le Tribunal fédéral rappelle qu'une expertise administrative peut se voir accorder une pleine valeur probante tant qu'aucun indice concret ne permet de douter de son bien-fondé.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Il précise qu'une divergence entre mandat thérapeutique et mandat d'expertise ne suffit pas à remettre en cause une expertise ordonnée par l'administration ou le juge.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "La juridiction cantonale retient que les limitations fonctionnelles alléguées par la personne assurée ne rendent pas illusoires ses perspectives de travail sur un marché équilibré.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "La juridiction cantonale conclut qu'un abattement de 10 % sur le revenu d'invalide ne permet pas d'atteindre un taux d'invalidité suffisant pour ouvrir le droit à une rente.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Le Tribunal fédéral retient que la juridiction cantonale a retenu sans arbitraire, sur la base des expertises du CEMed et du BEM, que la personne assurée dispose d'une pleine capacité de travail dans une activité adaptée.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral ajoute qu'un hypothétique abattement de 25 % sur le revenu d'invalide ne suffirait pas non plus à ouvrir le droit à une rente.",
      "b_propositions": ["P8"]
    }
  ]
}
